"""Supervised localhost whisper.cpp client using in-memory WAV requests."""

from __future__ import annotations

import io
import json
import subprocess
import urllib.error
import urllib.request
import wave
from collections.abc import Callable, Sequence
from urllib.parse import quote, urljoin

from dictate.privacy import PrivacyError, validate_loopback_url


class ASRError(RuntimeError):
	"""A content-free local ASR failure."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
	def redirect_request(self, request: object, fp: object, code: int, msg: str, headers: object, newurl: str) -> None:
		return None


def _wav(pcm: bytes) -> bytes:
	buffer = io.BytesIO()
	with wave.open(buffer, "wb") as output:
		output.setnchannels(1)
		output.setsampwidth(2)
		output.setframerate(16_000)
		output.writeframes(pcm)
	return buffer.getvalue()


class WhisperServer:
	"""Own one local whisper-server process for the lifetime of a service."""

	def __init__(
		self,
		endpoint: str,
		command: Sequence[str] | None = None,
		*,
		popen: Callable[..., subprocess.Popen[bytes]] = subprocess.Popen,
		opener: Callable[..., object] | None = None,
	) -> None:
		validate_loopback_url(endpoint)
		self.endpoint = endpoint.rstrip("/") + "/"
		self._command = tuple(command) if command else None
		self._popen = popen
		self._process: subprocess.Popen[bytes] | None = None
		self._opener = opener or urllib.request.build_opener(_NoRedirect()).open

	def start(self) -> None:
		if self._command is None or self._process is not None:
			return
		try:
			self._process = self._popen(self._command, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
		except OSError as error:
			raise ASRError("local ASR runtime could not start") from error

	def stop(self) -> None:
		if self._process is not None:
			self._process.terminate()
			self._process = None

	def ready(self) -> bool:
		self._ensure_running()
		request = urllib.request.Request(urljoin(self.endpoint, "health"), method="GET")
		try:
			with self._opener(request, timeout=2) as response:
				return 200 <= response.status < 300
		except (urllib.error.URLError, TimeoutError, OSError):
			return False

	def transcribe(self, pcm: bytes, terms: Sequence[str] = ()) -> str:
		if not pcm:
			raise ASRError("audio capture was empty")
		self._ensure_running()
		validate_loopback_url(self.endpoint)
		request = urllib.request.Request(
			urljoin(self.endpoint, "inference"),
			data=_wav(pcm),
			headers={"Content-Type": "audio/wav", "Accept": "application/json", "X-Whisper-Initial-Prompt": quote(", ".join(terms), safe="")},
			method="POST",
		)
		try:
			with self._opener(request, timeout=30) as response:
				if not 200 <= response.status < 300:
					raise ASRError("local ASR returned an unsuccessful status")
				payload = json.loads(response.read().decode("utf-8"))
		except (urllib.error.URLError, TimeoutError, OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
			raise ASRError("local ASR request failed") from error
		text = payload.get("text") if isinstance(payload, dict) else None
		if not isinstance(text, str) or not text.strip():
			raise ASRError("local ASR returned no usable transcription")
		return text.strip()

	def _ensure_running(self) -> None:
		if self._process is not None and self._process.poll() is not None:
			raise ASRError("local ASR runtime stopped unexpectedly")

"""Supervised localhost whisper.cpp client using in-memory WAV requests."""

from __future__ import annotations

import io
import json
import subprocess
import urllib.error
import urllib.request
import wave
from collections.abc import Callable, Sequence
from urllib.parse import quote, urljoin, urlparse

from dictate.config import Preferences
from dictate.privacy import PrivacyError, validate_loopback_url


class ASRError(RuntimeError):
	"""A content-free local ASR failure."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
	def redirect_request(self, request: object, fp: object, code: int, msg: str, headers: object, newurl: str) -> None:
		return None


def _wav(pcm: bytes) -> bytes:
	buffer = io.BytesIO()
	with wave.open(buffer, "wb") as output:
		output.setnchannels(1)
		output.setsampwidth(2)
		output.setframerate(16_000)
		output.writeframes(pcm)
	return buffer.getvalue()


def whisper_server_command(preferences: Preferences) -> tuple[str, ...]:
	"""Build the loopback-only command from installer-verified local artifacts."""
	if not preferences.whisper_server_executable or not preferences.whisper_model_path:
		raise ASRError("local ASR runtime and model must be installed")
	endpoint = urlparse(preferences.asr_endpoint)
	validate_loopback_url(preferences.asr_endpoint)
	if endpoint.port is None:
		raise ASRError("local ASR endpoint must include a port")
	return (preferences.whisper_server_executable, "--model", preferences.whisper_model_path, "--host", endpoint.hostname or "127.0.0.1", "--port", str(endpoint.port))


class WhisperServer:
	"""Own one local whisper-server process for the lifetime of a service."""

	def __init__(
		self,
		endpoint: str,
		command: Sequence[str] | None = None,
		*,
		popen: Callable[..., subprocess.Popen[bytes]] = subprocess.Popen,
		opener: Callable[..., object] | None = None,
	) -> None:
		validate_loopback_url(endpoint)
		self.endpoint = endpoint.rstrip("/") + "/"
		self._command = tuple(command) if command else None
		self._popen = popen
		self._process: subprocess.Popen[bytes] | None = None
		self._opener = opener or urllib.request.build_opener(_NoRedirect()).open

	def start(self) -> None:
		if self._command is None or self._process is not None:
			return
		try:
			self._process = self._popen(self._command, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
		except OSError as error:
			raise ASRError("local ASR runtime could not start") from error

	def stop(self) -> None:
		if self._process is not None:
			self._process.terminate()
			self._process = None

	def ready(self) -> bool:
		self._ensure_running()
		request = urllib.request.Request(urljoin(self.endpoint, "health"), method="GET")
		try:
			with self._opener(request, timeout=2) as response:
				return 200 <= response.status < 300
		except (urllib.error.URLError, TimeoutError, OSError):
			return False

	def transcribe(self, pcm: bytes, terms: Sequence[str] = ()) -> str:
		if not pcm:
			raise ASRError("audio capture was empty")
		self._ensure_running()
		validate_loopback_url(self.endpoint)
		request = urllib.request.Request(
			urljoin(self.endpoint, "inference"),
			data=_wav(pcm),
			headers={"Content-Type": "audio/wav", "Accept": "application/json", "X-Whisper-Initial-Prompt": quote(", ".join(terms), safe="")},
			method="POST",
		)
		try:
			with self._opener(request, timeout=30) as response:
				if not 200 <= response.status < 300:
					raise ASRError("local ASR returned an unsuccessful status")
				payload = json.loads(response.read().decode("utf-8"))
		except (urllib.error.URLError, TimeoutError, OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
			raise ASRError("local ASR request failed") from error
		text = payload.get("text") if isinstance(payload, dict) else None
		if not isinstance(text, str) or not text.strip():
			raise ASRError("local ASR returned no usable transcription")
		return text.strip()

	def _ensure_running(self) -> None:
		if self._process is not None and self._process.poll() is not None:
			raise ASRError("local ASR runtime stopped unexpectedly")

"""Standard-library-only console dispatcher for explicit dependency repair."""

from __future__ import annotations

import importlib.metadata
import subprocess
import sys
from collections.abc import Callable, Sequence

PYTHON_DEPENDENCIES = ("sounddevice==0.5.5", "pynput==1.8.2")


def is_explicit_install(argv: Sequence[str]) -> bool:
    """Accept exactly the one command permitted to modify dependencies."""
    return tuple(argv) == ("setup", "--install-dependencies")


def missing_dependencies() -> tuple[str, ...]:
    missing: list[str] = []
    for requirement in PYTHON_DEPENDENCIES:
        name, _, expected = requirement.partition("==")
        try:
            installed = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            installed = None
        if installed != expected:
            missing.append(requirement)
    return tuple(missing)


def repair_dependencies(
    requirements: Sequence[str], runner: Callable[[Sequence[str]], int] | None = None
) -> bool:
    if not requirements:
        return True
    run = runner or (lambda command: subprocess.run(tuple(command), check=False).returncode)
    try:
        return run((sys.executable, "-m", "pip", "install", *requirements)) == 0
    except OSError:
        return False


def main(
    argv: Sequence[str] | None = None,
    *,
    runner: Callable[[Sequence[str]], int] | None = None,
    import_cli: Callable[[], Callable[[list[str] | None], int]] | None = None,
) -> int:
    arguments = list(sys.argv[1:] if argv is None else argv)
    if is_explicit_install(arguments) and not repair_dependencies(missing_dependencies(), runner):
        print("setup: Python dependencies could not be installed; verify network access and retry", file=sys.stderr)
        return 1
    if import_cli is None:
        from dictate.cli import main as cli_main

        import_cli = lambda: cli_main
    return import_cli()(arguments)

"""Command-line entry point; commands remain content-free by contract."""

from __future__ import annotations

import argparse
import sys
import time
from pathlib import Path

from dictate.asr import WhisperServer
from dictate.audio import Recorder, list_input_devices
from dictate.cleanup import OllamaClient
from dictate.config import Preferences, load_preferences
from dictate.dictionary import global_dictionary_path, terms_for_paths
from dictate.platform import current_platform
from dictate.readiness import LocalReadiness
from dictate.service import DictationService, check_readiness


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="dictate", description="Local-only push-to-talk dictation")
    commands = parser.add_subparsers(dest="command", required=True)
    for name, help_text in (
        ("setup", "check required local setup"),
        ("serve", "start the local dictation service"),
        ("doctor", "run content-free readiness diagnostics"),
        ("devices", "list audio input devices"),
    ):
        command = commands.add_parser(name, help=help_text)
        if name == "serve":
            command.add_argument("--recover", action="store_true", help="print and clear an injected in-process recovery result (test-only)")
    return parser


def preferences_path(home: Path | None = None) -> Path:
    return (home or Path.home()) / ".config" / "dictate" / "preferences.toml"


def _report_readiness(command: str, preferences: Preferences) -> int:
    try:
        platform = current_platform()
        result = check_readiness(preferences, LocalReadiness(platform))
    except Exception:
        print(f"{command}: configuration or local capability check failed", file=sys.stderr)
        return 1
    for limitation in result.limitations:
        print(f"{command}: limitation: {limitation}", file=sys.stderr)
    if not result.ready:
        for failure in result.required_failures:
            print(f"{command}: not ready: {failure}", file=sys.stderr)
        return 1
    print(f"{command}: ready")
    return 0


def _serve(preferences: Preferences) -> int:
    try:
        platform = current_platform()
        result = check_readiness(preferences, LocalReadiness(platform))
    except Exception:
        print("serve: configuration or local capability check failed", file=sys.stderr)
        return 1
    if not result.ready:
        for failure in result.required_failures:
            print(f"serve: not ready: {failure}", file=sys.stderr)
        return 1
    for limitation in result.limitations:
        print(f"serve: limitation: {limitation}", file=sys.stderr)
    try:
        global_terms = terms_for_paths(global_dictionary_path())
    except (OSError, ValueError):
        print("serve: invalid local dictionary", file=sys.stderr)
        return 1
    service = DictationService(
        preferences,
        platform,
        Recorder(preferences.microphone),
        WhisperServer(preferences.asr_endpoint),
        OllamaClient(preferences.ollama_endpoint, preferences.ollama_model),
        status=lambda event: print(f"serve: {event}", file=sys.stderr),
        terms_for_target=lambda _target: global_terms,
    )
    try:
        service.start()
    except Exception:
        service.stop()
        print("serve: could not start local dictation service", file=sys.stderr)
        return 1
    print("serve: ready", file=sys.stderr)
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        return 0
    finally:
        service.stop()


def main(argv: list[str] | None = None, *, recovery: object | None = None) -> int:
    args = build_parser().parse_args(argv)
    if args.command == "serve" and args.recover:
        from dictate.service import DEFAULT_RECOVERY

        result = (recovery or DEFAULT_RECOVERY).take()
        if result is None:
            print("no recovery result is available", file=sys.stderr)
            return 1
        print(result)
        return 0
    try:
        preferences = load_preferences(preferences_path())
    except (OSError, ValueError):
        print(f"{args.command}: invalid local preferences", file=sys.stderr)
        return 1
    if args.command == "devices":
        try:
            devices = list_input_devices()
        except Exception:
            print("devices: could not inspect local audio inputs", file=sys.stderr)
            return 1
        if not devices:
            print("devices: no local audio inputs are available", file=sys.stderr)
            return 1
        for device in devices:
            print(f"{device.identifier}\t{device.name}")
        return 0
    if args.command in ("setup", "doctor"):
        return _report_readiness(args.command, preferences)
    return _serve(preferences)

"""Command-line entry point; commands remain content-free by contract."""

from __future__ import annotations

import argparse
import sys
import time
from pathlib import Path

from dictate.asr import WhisperServer
from dictate.audio import Recorder, list_input_devices
from dictate.cleanup import OllamaClient
from dictate.config import Preferences, load_preferences
from dictate.dictionary import global_dictionary_path, terms_for_paths
from dictate.installer import InstallerCoordinator
from dictate.platform import current_platform
from dictate.readiness import LocalReadiness
from dictate.service import DictationService, check_readiness


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="dictate", description="Local-only push-to-talk dictation")
    commands = parser.add_subparsers(dest="command", required=True)
    for name, help_text in (
        ("setup", "check required local setup"),
        ("serve", "start the local dictation service"),
        ("doctor", "run content-free readiness diagnostics"),
        ("devices", "list audio input devices"),
    ):
        command = commands.add_parser(name, help=help_text)
        if name == "setup":
            command.add_argument("--install-dependencies", action="store_true", help="explicitly acquire missing local default dependencies")
        if name == "serve":
            command.add_argument("--recover", action="store_true", help="print and clear an injected in-process recovery result (test-only)")
    return parser


def preferences_path(home: Path | None = None) -> Path:
    return (home or Path.home()) / ".config" / "dictate" / "preferences.toml"


def _report_readiness(command: str, preferences: Preferences) -> int:
    try:
        platform = current_platform()
        result = check_readiness(preferences, LocalReadiness(platform))
    except Exception:
        print(f"{command}: configuration or local capability check failed", file=sys.stderr)
        return 1
    for limitation in result.limitations:
        print(f"{command}: limitation: {limitation}", file=sys.stderr)
    if not result.ready:
        for failure in result.required_failures:
            print(f"{command}: not ready: {failure}", file=sys.stderr)
        if command == "setup" and any(failure.startswith(("local ASR:", "local Ollama model:")) for failure in result.required_failures):
            print("setup: run dictate setup --install-dependencies to acquire missing default local components", file=sys.stderr)
        return 1
    print(f"{command}: ready")
    return 0


def _install_dependencies(preferences: Preferences, path: Path) -> tuple[bool, Preferences]:
    """Run the only mutable setup path and keep all output content-free."""
    coordinator = InstallerCoordinator(current_platform(), path)
    results = coordinator.install(preferences)
    failed = False
    for result in results:
        message = f"setup: {result.component}: {result.status}"
        if result.remediation:
            message = f"{message}: {result.remediation}"
        print(message, file=sys.stderr)
        failed = failed or result.status in ("failed", "unsupported")
    if failed:
        return False, preferences
    try:
        return True, load_preferences(path)
    except (OSError, ValueError):
        print("setup: verified local runtime settings could not be loaded", file=sys.stderr)
        return False, preferences


def _serve(preferences: Preferences) -> int:
    try:
        platform = current_platform()
        result = check_readiness(preferences, LocalReadiness(platform))
    except Exception:
        print("serve: configuration or local capability check failed", file=sys.stderr)
        return 1
    if not result.ready:
        for failure in result.required_failures:
            print(f"serve: not ready: {failure}", file=sys.stderr)
        return 1
    for limitation in result.limitations:
        print(f"serve: limitation: {limitation}", file=sys.stderr)
    try:
        global_terms = terms_for_paths(global_dictionary_path())
    except (OSError, ValueError):
        print("serve: invalid local dictionary", file=sys.stderr)
        return 1
    service = DictationService(
        preferences,
        platform,
        Recorder(preferences.microphone),
        WhisperServer(preferences.asr_endpoint),
        OllamaClient(preferences.ollama_endpoint, preferences.ollama_model),
        status=lambda event: print(f"serve: {event}", file=sys.stderr),
        terms_for_target=lambda _target: global_terms,
    )
    try:
        service.start()
    except Exception:
        service.stop()
        print("serve: could not start local dictation service", file=sys.stderr)
        return 1
    print("serve: ready", file=sys.stderr)
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        return 0
    finally:
        service.stop()


def main(argv: list[str] | None = None, *, recovery: object | None = None) -> int:
    args = build_parser().parse_args(argv)
    if args.command == "serve" and args.recover:
        from dictate.service import DEFAULT_RECOVERY

        result = (recovery or DEFAULT_RECOVERY).take()
        if result is None:
            print("no recovery result is available", file=sys.stderr)
            return 1
        print(result)
        return 0
    path = preferences_path()
    try:
        preferences = load_preferences(path)
    except (OSError, ValueError):
        print(f"{args.command}: invalid local preferences", file=sys.stderr)
        return 1
    if args.command == "devices":
        try:
            devices = list_input_devices()
        except Exception:
            print("devices: could not inspect local audio inputs", file=sys.stderr)
            return 1
        if not devices:
            print("devices: no local audio inputs are available", file=sys.stderr)
            return 1
        for device in devices:
            print(f"{device.identifier}\t{device.name}")
        return 0
    if args.command == "setup" and args.install_dependencies:
        installed, preferences = _install_dependencies(preferences, path)
        return _report_readiness("setup", preferences) if installed else 1
    if args.command in ("setup", "doctor"):
        return _report_readiness(args.command, preferences)
    return _serve(preferences)

"""Directly editable TOML preferences with safe defaults."""

from __future__ import annotations

import os
import tempfile
import tomllib
from dataclasses import dataclass
from pathlib import Path

from dictate.privacy import validate_loopback_url

STYLES = ("Natural", "Formal", "Casual", "Technical")
DEFAULT_TRIGGER = "right_alt"
DEFAULT_OLLAMA_ENDPOINT = "http://127.0.0.1:11434"
DEFAULT_ASR_ENDPOINT = "http://127.0.0.1:8080"
DEFAULT_OLLAMA_MODEL = "qwen3:4b-instruct-2507-q4_K_M"
DEFAULT_WHISPER_MODEL = "ggml-base.bin"


@dataclass(frozen=True)
class Preferences:
    microphone: str = "system-default"
    trigger: str = DEFAULT_TRIGGER
    style: str = "Natural"
    asr_endpoint: str = DEFAULT_ASR_ENDPOINT
    ollama_endpoint: str = DEFAULT_OLLAMA_ENDPOINT
    ollama_model: str = DEFAULT_OLLAMA_MODEL
    context_limit: int = 1_024
    whisper_server_executable: str | None = None
    whisper_model_path: str | None = None


def validate_preferences(preferences: Preferences) -> Preferences:
    if not all(isinstance(value, str) for value in (
        preferences.microphone,
        preferences.trigger,
        preferences.style,
        preferences.asr_endpoint,
        preferences.ollama_endpoint,
        preferences.ollama_model,
    )):
        raise ValueError("string preferences must be TOML strings")
    if isinstance(preferences.context_limit, bool) or not isinstance(preferences.context_limit, int):
        raise ValueError("context_limit must be a TOML integer")
    if preferences.microphone == "":
        raise ValueError("microphone must be system-default or a device identifier")
    if not preferences.trigger:
        raise ValueError("trigger must not be empty")
    if preferences.style not in STYLES:
        raise ValueError(f"style must be one of: {', '.join(STYLES)}")
    if preferences.context_limit <= 0:
        raise ValueError("context_limit must be positive")
    validate_loopback_url(preferences.asr_endpoint)
    validate_loopback_url(preferences.ollama_endpoint)
    if not preferences.ollama_model:
        raise ValueError("ollama_model must not be empty")
    for name in ("whisper_server_executable", "whisper_model_path"):
        value = getattr(preferences, name)
        if value is not None:
            if not isinstance(value, str) or not value or "\x00" in value or not Path(value).is_absolute():
                raise ValueError(f"{name} must be an absolute local path when configured")
    return preferences


def load_preferences(path: Path) -> Preferences:
    if not path.exists():
        return validate_preferences(Preferences())
    with path.open("rb") as file:
        data = tomllib.load(file)
    unknown = set(data) - set(Preferences.__annotations__)
    if unknown:
        raise ValueError(f"unknown preference: {sorted(unknown)[0]}")
    try:
        preferences = Preferences(**data)
    except TypeError as error:
        raise ValueError("invalid preferences TOML") from error
    return validate_preferences(preferences)


def save_preferences(path: Path, preferences: Preferences) -> None:
    preferences = validate_preferences(preferences)
    path.parent.mkdir(parents=True, exist_ok=True)
    content = "\n".join(f'{name} = {value!r}' for name, value in vars(preferences).items() if value is not None) + "\n"
    descriptor, temporary_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as file:
            file.write(content)
            file.flush()
            os.fsync(file.fileno())
        os.replace(temporary_name, path)
    except BaseException:
        try:
            os.unlink(temporary_name)
        except FileNotFoundError:
            pass
        raise

"""Explicit, content-free acquisition of Dictate's local default pipeline."""

from __future__ import annotations

import importlib.metadata
import os
import shutil
import subprocess
import tempfile
import urllib.error
import urllib.request
from collections.abc import Callable, Sequence
from dataclasses import dataclass, replace
from pathlib import Path
from typing import Literal, Protocol

from dictate.cleanup import OllamaClient
from dictate.config import DEFAULT_OLLAMA_MODEL, DEFAULT_WHISPER_MODEL, Preferences, save_preferences

ComponentStatus = Literal["retained", "acquired", "failed", "unsupported"]
PYTHON_DEPENDENCIES = ("sounddevice==0.5.5", "pynput==1.8.2")
COMPONENTS = ("python-dependencies", "whisper-runtime", "whisper-model", "ollama-runtime", "ollama-model")
DEFAULT_WHISPER_MODEL_URL = "https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-base.bin"


@dataclass(frozen=True)
class ComponentResult:
    """A command-scoped status which never includes paths, URLs, or tool output."""

    component: str
    status: ComponentStatus
    remediation: str | None = None


class RuntimeAcquirer(Protocol):
    def acquire_external_runtime(self, component: str, runner: Callable[[Sequence[str]], bool]) -> object: ...


class InstallerCoordinator:
    """Acquire only missing default components after an explicit CLI request."""

    def __init__(
        self,
        platform: RuntimeAcquirer,
        preferences_path: Path,
        *,
        executable_finder: Callable[[str], str | None] | None = None,
        runner: Callable[[Sequence[str]], bool] | None = None,
        downloader: Callable[[str, Path], None] | None = None,
        package_ready: Callable[[str], bool] | None = None,
        ollama_ready: Callable[[str, str], bool] | None = None,
        saver: Callable[[Path, Preferences], None] = save_preferences,
        model_url: str = DEFAULT_WHISPER_MODEL_URL,
    ) -> None:
        self._platform = platform
        self._preferences_path = preferences_path
        self._executable_finder = executable_finder or self._find_executable
        self._runner = runner or self._run
        self._downloader = downloader or self._download
        self._package_ready = package_ready or self._package_is_ready
        self._ollama_ready = ollama_ready or self._ollama_is_ready
        self._saver = saver
        self._model_url = model_url

    def install(self, preferences: Preferences) -> tuple[ComponentResult, ...]:
        """Return fixed-order component outcomes; never claim final service readiness."""
        results: list[ComponentResult] = [self._python_dependencies()]
        executable, runtime_result = self._whisper_runtime(preferences)
        results.append(runtime_result)
        model, model_result = self._whisper_model(preferences)
        results.append(model_result)
        if executable and model:
            try:
                self._saver(
                    self._preferences_path,
                    replace(preferences, whisper_server_executable=str(executable), whisper_model_path=str(model)),
                )
            except OSError:
                results[-1] = ComponentResult("whisper-model", "failed", "could not save verified local runtime settings")
        results.append(self._external_runtime("ollama-runtime", "ollama"))
        results.append(self._ollama_model(preferences))
        return tuple(results)

    def _python_dependencies(self) -> ComponentResult:
        return ComponentResult(
            "python-dependencies",
            "retained" if all(self._package_ready(requirement) for requirement in PYTHON_DEPENDENCIES) else "failed",
            None if all(self._package_ready(requirement) for requirement in PYTHON_DEPENDENCIES) else "rerun explicit setup to repair Python dependencies",
        )

    def _whisper_runtime(self, preferences: Preferences) -> tuple[Path | None, ComponentResult]:
        candidate = self._usable_file(preferences.whisper_server_executable) or self._which_file("whisper-server")
        if candidate:
            return candidate, ComponentResult("whisper-runtime", "retained")
        acquired = self._platform.acquire_external_runtime("whisper-runtime", self._runner)
        if not acquired.acquired:
            return None, ComponentResult("whisper-runtime", "unsupported" if acquired.remediation == "unsupported local runtime acquisition" else "failed", acquired.remediation)
        candidate = self._which_file("whisper-server")
        if not candidate:
            return None, ComponentResult("whisper-runtime", "failed", "local whisper runtime was not available after installation")
        return candidate, ComponentResult("whisper-runtime", "acquired")

    def _whisper_model(self, preferences: Preferences) -> tuple[Path | None, ComponentResult]:
        candidate = self._usable_file(preferences.whisper_model_path)
        if candidate:
            return candidate, ComponentResult("whisper-model", "retained")
        destination = self._preferences_path.parent / "models" / DEFAULT_WHISPER_MODEL
        if destination.is_file() and destination.stat().st_size > 0:
            return destination, ComponentResult("whisper-model", "retained")
        destination.parent.mkdir(parents=True, exist_ok=True)
        descriptor, temporary_name = tempfile.mkstemp(prefix=f".{DEFAULT_WHISPER_MODEL}.", dir=destination.parent)
        os.close(descriptor)
        temporary = Path(temporary_name)
        try:
            self._downloader(self._model_url, temporary)
            if not temporary.is_file() or temporary.stat().st_size == 0:
                raise OSError("empty artifact")
            os.replace(temporary, destination)
            return destination, ComponentResult("whisper-model", "acquired")
        except (OSError, PermissionError, urllib.error.URLError):
            return None, ComponentResult("whisper-model", "failed", "make local storage and network access available for the speech model")
        finally:
            try:
                temporary.unlink()
            except FileNotFoundError:
                pass

    def _external_runtime(self, component: str, executable: str) -> ComponentResult:
        if self._which_file(executable):
            return ComponentResult(component, "retained")
        acquired = self._platform.acquire_external_runtime(component, self._runner)
        if not acquired.acquired:
            return ComponentResult(component, "unsupported" if acquired.remediation == "unsupported local runtime acquisition" else "failed", acquired.remediation)
        if not self._which_file(executable):
            return ComponentResult(component, "failed", "local runtime was not available after installation")
        return ComponentResult(component, "acquired")

    def _ollama_model(self, preferences: Preferences) -> ComponentResult:
        if self._ollama_ready(preferences.ollama_endpoint, preferences.ollama_model):
            return ComponentResult("ollama-model", "retained")
        if not self._runner(("ollama", "pull", preferences.ollama_model or DEFAULT_OLLAMA_MODEL)):
            return ComponentResult("ollama-model", "failed", "start local Ollama and make network access available for the cleanup model")
        if not self._ollama_ready(preferences.ollama_endpoint, preferences.ollama_model):
            return ComponentResult("ollama-model", "failed", "start local Ollama and verify the cleanup model")
        return ComponentResult("ollama-model", "acquired")

    def _usable_file(self, value: str | None) -> Path | None:
        if not value:
            return None
        path = Path(value)
        return path if path.is_file() and path.stat().st_size > 0 else None

    def _which_file(self, executable: str) -> Path | None:
        value = self._executable_finder(executable)
        return self._usable_file(value)

    @staticmethod
    def _find_executable(executable: str) -> str | None:
        return shutil.which(executable)

    @staticmethod
    def _run(command: Sequence[str]) -> bool:
        try:
            return subprocess.run(tuple(command), stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False).returncode == 0
        except OSError:
            return False

    @staticmethod
    def _download(url: str, destination: Path) -> None:
        with urllib.request.urlopen(url, timeout=60) as response, destination.open("wb") as output:
            shutil.copyfileobj(response, output)

    @staticmethod
    def _package_is_ready(requirement: str) -> bool:
        name, _, expected = requirement.partition("==")
        try:
            return importlib.metadata.version(name) == expected
        except importlib.metadata.PackageNotFoundError:
            return False

    @staticmethod
    def _ollama_is_ready(endpoint: str, model: str) -> bool:
        try:
            return OllamaClient(endpoint, model).ready()
        except Exception:
            return False

"""The only polymorphic boundary for OS integration."""

